import {HrStore,seed} from './operations.mjs?v=20261117-shifts-4';
import {policyBalance as balance} from './workflows.mjs?v=20261117-shifts-4';
import {createAdvanced} from './advanced-ui.mjs?v=20261117-shifts-4';
import {money,dateText,escapeHTML as esc,csv,iso,DAY} from './model.mjs?v=20261117-shifts-4';
const KEY='ototr.ik2.demo.v2', $=s=>document.querySelector(s);
let loaded;try{loaded=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}
const store=new HrStore(loaded||seed(),{persist:data=>{const current=JSON.parse(localStorage.getItem(KEY)||'null');if(current&&current.revision!==data.revision-1)throw Error('Demo başka sekmede değişmiş. Sayfayı yenileyin.');localStorage.setItem(KEY,JSON.stringify(data));}});
let route='home',sub='',employeeId='e1',search='',branch='',employeeView='cards',calendarMonth=store.state.today.slice(0,7),calendarView='month';
const names={pending:'Onay bekliyor',approved:'Onaylandı',rejected:'Reddedildi',cancelled:'İptal',active:'Aktif',inactive:'Pasif',draft:'Taslak',published:'Yayınlandı',completed:'Tamamlandı',interview:'Görüşme',offer:'Teklif',hired:'İşe alındı'};
const nav=[['home','Ana Sayfa','layout-dashboard'],['employees','Çalışanlar','users'],['leaves','İzinler','plane'],['reports','Raporlar','chart-column'],['calendar','Takvim','calendar-days'],['payroll','Bordro','badge-dollar-sign'],['shifts','Vardiya Yönetimi','clock-3'],['performance','Performans Değerlendirme','trophy'],['compensation','Ücret Değerlendirme','briefcase-business']];
const extra=[['clock','Demo PDKS','timer'],['visa','Vize Belgeleri','file-check'],['timesheets','Puantaj','table'],['expenses','Harcamalar','wallet'],['overtime','Mesai Yönetimi','clock'],['documents','Dosyalar','files'],['assets','Zimmetler','package'],['trainings','Eğitimler','graduation-cap'],['candidates','İşe Alım','user-plus'],['workflows','İş Akışları','workflow'],['notifications','Bildirimler','bell'],['audit','İşlem Geçmişi','history']];
const icon=name=>`<i data-lucide="${name}" aria-hidden="true"></i>`;
const btn=(label,action,cls='',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const badge=status=>`<span class="badge ${esc(status)}">${esc(names[status]||status)}</span>`;
const initials=name=>name.split(' ').map(x=>x[0]).slice(0,2).join('');
const avatar=(e,small=false)=>`<span class="avatar ${small?'small':''}">${esc(initials(e?.name||'?'))}</span>`;
const emp=id=>store.state.employees.find(x=>x.id===id);
const person=id=>{const e=emp(id);return e?`<a class="person" href="#employee/${e.id}/profile">${avatar(e,true)}<span>${esc(e.name)}</span></a>`:'—';};
const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c??'—'}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty">Kayıt bulunamadı.</td></tr>`}</tbody></table></div>`;
const panel=(title,body,ico='users',footer='')=>`<section class="panel"><h2>${icon(ico)}${title}</h2><div class="panel-body">${body}</div>${footer?`<div class="panel-footer">${footer}</div>`:''}</section>`;
const empty=(text,action='')=>`<div class="empty">${icon('inbox')}<h3>${text}</h3>${action}</div>`;
const notice=text=>`<div class="notice">${text}</div>`;
const field=(name,label,type='text',value='',options=null,full=false)=>`<label class="field ${full?'full':''}"><span>${label}</span>${options?`<select name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(names[l]||l)}</option>`;}).join('')}</select>`:type==='textarea'?`<textarea name="${name}">${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${['number'].includes(type)?'step="any"':''}>`}</label>`;
const check=(name,label,value)=>`<label class="check"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`;
const employeeOptions=()=>store.readable('employees').filter(x=>x.status==='active').map(x=>[x.id,x.name]);
function tabs(items,current){$('#tabs').innerHTML=items.map(([id,title])=>btn(title,'tab',id===current?'active':'',`data-tab="${id}"`)).join('');}
function header(title,description='',actions=''){$('#header').innerHTML=`<div class="person">${btn(icon('menu'),'mobile','mobile-menu','aria-label="Menüyü aç"')}<div><h1>${esc(title)}</h1>${description?`<p>${esc(description)}</p>`:''}</div></div><div class="actions">${actions}</div>`;}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000);}
function download(name,content,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function modal(title,body,onSave,saveLabel='Kaydet',wide=false){const d=$('#dialog');d.className=wide?'wide':'';d.innerHTML=`<form><div class="modal-head"><h2>${title}</h2><button type="button" data-action="close" aria-label="Kapat">×</button></div><div class="modal-body"><div class="error" role="alert"></div>${body}</div><div class="modal-foot"><button type="button" data-action="close">İptal</button>${onSave?`<button class="primary" type="submit">${saveLabel}</button>`:''}</div></form>`;d.querySelector('form').onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.currentTarget));for(const box of d.querySelectorAll('input[type=checkbox]'))values[box.name]=box.checked;try{const saved=await onSave(values);d.close();if(saved===false)return;render();toast('Kaydedildi.');}catch(error){d.querySelector('.error').textContent=error.message;}};d.showModal();icons();}
function icons(){window.lucide?.createIcons();}
function navigate(value){location.hash=value;}
function filteredEmployees(){return store.readable('employees').filter(e=>(!sessionStorage.getItem('ik2.employeeStatus')||sessionStorage.getItem('ik2.employeeStatus')==='all'||e.status===sessionStorage.getItem('ik2.employeeStatus'))&&(!search||e.name.toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr')))&&(!branch||e.branch===branch));}
function searchToolbar(extraHtml=''){return `<div class="toolbar"><input id="search" aria-label="Ara" placeholder="Ara" value="${esc(search)}"><div class="filters">${extraHtml}</div></div>`;}
function home(){const s=store.state,e=emp(store.actor),b=balance(s,e.id);header(`Merhaba ${e.name.split(' ')[0]}!`,'İşinizde başarı dolu nice yıllar dileriz.');const req=(type)=>store.readable('requests').filter(x=>x.type===type&&x.status==='pending').map(x=>`<div class="list-row">${avatar(emp(x.employeeId),true)}<a class="grow" href="#${type==='İzin'?'leaves':type==='Fazla Mesai'?'overtime':'expenses'}">${esc(emp(x.employeeId).name)}</a><span class="warn">${x.days?`${x.days}g`:x.hours?`${x.hours}s`:money(x.amount)}</span></div>`).join('')||'<span class="muted">Bekleyen talep yok.</span>';const branchChart=s.settings.branches.map(x=>`<div class="chart-row"><span>${esc(x)}</span><div class="bar"><span style="width:${store.readable('employees').filter(e=>e.branch===x).length/s.employees.length*100}%"></span></div><b>${store.readable('employees').filter(e=>e.branch===x).length}</b></div>`).join('');return `<div class="dashboard"><div class="column">${panel(e.name,`${avatar(e)}<p>${esc(e.title)}</p><p class="muted">${esc(e.department)}</p><hr><p class="muted">İşe Başlama Tarihi</p>${dateText(e.start)}`,'user',`<a href="#employee/${e.id}/profile">Hesabım ›</a>`)}${panel('İzin Bilgilerim',`<span class="muted">Yıllık İzin</span><div class="metric">${b.available} gün</div><div class="bar"><span style="width:${Math.max(0,b.available/b.entitled*100)}%"></span></div><p class="muted">Bekleyen ${b.pending} · Kullanılan ${b.used}</p>${btn('İzin Talep Et','request','','data-type="İzin"')}`,'plane')}</div><div class="column">${panel('Çalışan Dağılımı',branchChart,'chart-pie',`<a href="#reports">Raporlara git ›</a>`)}${panel('Astlarım',store.readable('employees').filter(x=>x.managerId===e.id).map(x=>`<div class="list-row">${person(x.id)}</div>`).join('')||'Ast bulunamadı.','users')}</div><div class="column">${panel('Etkinlik Takvimi',s.events.map(x=>`<div class="list-row"><a href="#calendar" class="grow">${esc(x.title)}</a>${dateText(x.start)}</div>`).join(''),'calendar-days',`<a href="#calendar">Tümünü Görün ›</a>`)}${panel('Yaklaşan İzinler',store.readable('requests').filter(x=>x.type==='İzin'&&x.status==='approved').map(x=>`<div class="list-row">${person(x.employeeId)}<span>${dateText(x.start)}</span></div>`).join('')||'<span class="muted">Yaklaşan izin bulunmuyor.</span>','plane')}${panel('Yaklaşan Doğum Günleri','<span class="muted">Bu ay doğum günü bulunmuyor.</span>','cake')}</div><div class="column">${panel('İzin Talepleri',req('İzin'),'plane',`<a href="#leaves">Tümünü Görün ›</a>`)}${panel('Ödeme Talepleri',req('Harcama')+req('Avans'),'wallet')}${panel('Mesai Talepleri',req('Fazla Mesai'),'clock')}</div></div>`;}
function employees(){header(`${store.readable('employees').filter(x=>x.status==='active').length} Çalışan`,'',btn('Toplu İşlemler','bulk')+btn('İçe Aktar','import-data')+btn('Yeni Çalışan Ekle','employee-new','primary'));const rows=filteredEmployees();return searchToolbar(`<select id="employment-status" aria-label="Çalışan durumu">${[['all','Tüm çalışanlar'],['active','Aktif'],['inactive','Pasif']].map(([value,label])=>`<option value="${value}" ${(sessionStorage.getItem('ik2.employeeStatus')||'all')===value?'selected':''}>${label}</option>`).join('')}</select><select id="branch" aria-label="Şube"><option value="">Tüm Birimler</option>${store.state.settings.branches.map(x=>`<option ${branch===x?'selected':''}>${esc(x)}</option>`).join('')}</select>${btn(icon('grid-3x3'),'view','','data-view="cards" aria-label="Kart görünümü"')}${btn(icon('list'),'view','','data-view="table" aria-label="Liste görünümü"')}${btn(icon('network'),'view','','data-view="org" aria-label="Organizasyon şeması"')}`)+(employeeView==='cards'?`<div class="cards">${rows.map(e=>`<a class="employee-card" href="#employee/${e.id}/profile">${avatar(e)}<span>${esc(e.name)}</span><small>${esc(e.title)}</small><small>${esc(e.branch)}</small>${badge(e.status)}</a>`).join('')}</div>`:employeeView==='org'?organization(rows):table(['Ad Soyad','Unvan','Şube','Departman','İşe Başlama','Durum'],rows.map(e=>[person(e.id),esc(e.title),esc(e.branch),esc(e.department),dateText(e.start),badge(e.status)])));}
function organization(rows){if(!rows.length)return empty('Çalışan bulunamadı.');const visible=new Set(rows.map(e=>e.id));const tree=e=>`<li>${person(e.id)}<small> · ${esc(e.title)}</small>${rows.some(x=>x.managerId===e.id)?`<ul>${rows.filter(x=>x.managerId===e.id).map(tree).join('')}</ul>`:''}</li>`;return `<div class="org-tree"><ul>${rows.filter(e=>!e.managerId||!visible.has(e.managerId)).map(tree).join('')}</ul></div>`;}
function employee(){const e=emp(employeeId);if(!e)return empty('Çalışan bulunamadı.');const sections=[['profile','Profil'],['personal','Kişisel Bilgiler'],['career','Kariyer'],['custom','Özel Alanlar'],['leave','İzinler'],['payments','Ödemeler'],['payslips','Bordro'],['overtime','Mesailer'],['assets','Zimmetler'],['trainings','Eğitimler'],['documents','Dosyalar']];header(e.name,e.title,btn('Düzenle','employee-edit')+btn(e.status==='active'?'Pasife Al':'Aktifleştir','employee-status'));tabs(sections,sub||'profile');const detail=items=>`<div class="detail-grid">${items.map(([k,v])=>`<div><label>${k}</label>${esc(v||'—')}</div>`).join('')}</div>`;if(store.role==='manager'&&e.id!==store.actor&&['personal','career','payslips','payments','documents'].includes(sub))return notice('Bu özlük bölümü yalnızca İK ve ilgili çalışana açıktır.');if(sub==='personal')return `<div class="profile-grid"><div class="column">${panel('Vatandaşlık',detail([['Doğum Tarihi',dateText(e.birth)],['Kimlik Numarası',e.identity],['Cinsiyet',e.gender],['Uyruğu',e.nationality],['Askerlik',e.personal.military],['Engellilik Bilgisi',e.personal.disability]]),'user')}${panel('Eğitim ve Aile',detail([['Eğitim',e.personal.education],['Medeni Hal',e.personal.marital],['Okul',e.personal.school],['Mezuniyet',e.personal.graduation],['Çocuk Sayısı',e.personal.children]]),'graduation-cap')}${panel('Adres ve Banka',detail([['Adres',e.personal.address],['Banka',e.personal.bank],['IBAN',e.personal.iban]]),'map-pin')}</div><div>${panel('Acil Durum',detail([['Ad Soyad',e.personal.emergencyName],['Telefon',e.personal.emergencyPhone]]),'phone')}</div></div>`;if(sub==='career')return `<div class="subtabs">${btn('Pozisyon Ekle','position')}${btn('Maaş Güncelle','salary')}</div>${panel('Güncel Pozisyon',detail([['Şirket','OTOTR'],['Şube',e.branch],['Departman',e.department],['Unvan',e.title],['Çalışma Şekli',e.workType],['İşe Başlama',dateText(e.start)]]),'briefcase')}<h3>Pozisyon Geçmişi</h3>${table(['Başlangıç','Şube','Departman','Unvan'],e.positions.map(p=>[dateText(p.start)+(p.scheduled?' · Planlandı':''),esc(p.branch),esc(p.department),esc(p.title)]))}<h3>Maaş Geçmişi</h3>${table(['Durum / Değişiklik Tarihi','Tutar','Ücret Türü'],[['Güncel maaş',money(e.salary),esc(e.salaryType)],...e.salaryHistory.map(p=>[dateText(p.start)+(p.scheduled?' · Planlanan':p.appliedAt?' · Uygulanan':' · Değişiklik öncesi'),money(p.amount),esc(p.type)])])}`;if(sub==='leave'){const b=balance(store.state,e.id);return `<div class="stat-row">${[['Hak Edilen',b.entitled],['Kullanılan',b.used],['Bekleyen',b.pending],['Kullanılabilir',b.available]].map(([a,v])=>`<div><span>${a}</span><strong>${v} gün</strong></div>`).join('')}</div>${btn('İzin Ekle','request','primary',`data-type="İzin" data-employee="${e.id}"`)}<br><br>${requestsTable(store.readable('requests').filter(x=>x.employeeId===e.id&&x.type==='İzin'))}`;}if(sub==='payments'||sub==='overtime')return `${btn('Talep Ekle','request','primary',`data-type="${sub==='overtime'?'Fazla Mesai':'Harcama'}" data-employee="${e.id}"`)}<br><br>${requestsTable(store.readable('requests').filter(x=>x.employeeId===e.id&&(sub==='overtime'?x.type==='Fazla Mesai':['Harcama','Avans'].includes(x.type))))}`;if(sub==='documents')return advanced.views.documents(e.id);if(['assets','trainings'].includes(sub))return records(sub,e.id);if(sub==='payslips')return table(['Dönem','Brüt','Kesinti','Demo Net'],store.state.payrolls.flatMap(p=>p.rows.filter(r=>r.employeeId===e.id).map(r=>[p.month,money(r.gross),money(r.contribution+r.tax),money(r.net)])));if(sub==='custom')return store.state.customFields.length?btn('Değerleri Düzenle','custom-edit')+table(['Alan','Değer'],store.state.customFields.map(x=>[esc(x.title),esc(e.custom?.[x.id]||'—')])):empty('Henüz özel alan tanımlanmamış.',btn('Özel Alan Oluştur','record-new','','data-collection="customFields"'));return `<div class="profile-grid"><div class="column">${panel(e.name,`${avatar(e)}${detail([['İşe Başlama Tarihi',dateText(e.start)],['Çalışma Şekli',e.workType],['Şirket','OTOTR'],['Şube',e.branch],['Departman',e.department],['Unvan',e.title]])}`,'user')}${panel('Astları',store.state.employees.filter(x=>x.managerId===e.id).map(x=>`<div class="list-row">${person(x.id)}</div>`).join('')||'<span class="muted">Astı bulunmuyor.</span>','users')}</div><div class="column">${panel('Yöneticisi',e.managerId?person(e.managerId):'—','user-check')}${panel('İletişim',detail([['E-posta (İş)',e.email],['Telefon (İş)',e.phone]]),'phone')}${panel('Erişim',detail([['Çalışan Durumu',names[e.status]],['Veri Ortamı','Kurgusal demo']]),'shield-check')}</div></div>`;}
function requestsTable(rows){rows=rows.filter(r=>store.canReadRequest(r));return table(['Çalışan','Tür','Tarih','Süre / Tutar','Açıklama','Durum','İşlemler'],rows.map(r=>[person(r.employeeId),esc(r.leaveType||r.type),dateText(r.start||r.createdAt),r.days?`${r.days} gün`:r.hours?`${r.hours} saat`:r.amount?money(r.amount):'—',esc(r.note||'—')+(r.type==='Vize Belgesi'&&r.status==='approved'?btn('Demo Belge İndir','visa-download','',`data-id="${r.id}"`):'')+(r.receiptId?' '+btn('Fişi İndir','file-download','text-button',`data-id="${r.receiptId}"`):''),badge(r.status)+(r.paid?' <span class="badge approved">Ödendi</span>':''),r.status==='pending'&&store.role!=='employee'&&(r.approvers||store.approvers(r.employeeId))[r.approvals?.length||0]===store.actor?btn('Onayla','approve','text-button',`data-id="${r.id}"`)+btn('Reddet','reject','text-button danger',`data-id="${r.id}"`):r.status==='approved'&&store.role==='admin'&&['Harcama','Avans'].includes(r.type)&&!r.paid?btn('Demo Ödendi','paid','text-button',`data-id="${r.id}"`):['pending','approved'].includes(r.status)&&!r.paid&&(store.role==='admin'||r.employeeId===store.actor)?btn('İptal','request-cancel','text-button',`data-id="${r.id}"`):'—']));}
function leaves(){header('İzinler','',btn('İzin Talep Et','request','primary','data-type="İzin"'));tabs([['list','İzinler'],['balances','Raporlar'],['policies','Kurallar'],['approval','Onay Süreçleri'],['calendar','Takvim']],sub||'list');if(sub==='balances')return table(['Çalışan','Hak Edilen','Kullanılan','Bekleyen','Kullanılabilir'],store.readable('employees').map(e=>{const b=balance(store.state,e.id);return [person(e.id),b.entitled,b.used,b.pending,b.available];}));if(sub==='policies')return notice('Politikalar çalışanlara ayrı ayrı atanabilir. Bekleyen izinleri sonuçlandırmadan politika değiştirilemez.')+btn('Yeni Politika','policy','primary','data-id="new"')+' '+btn('Çalışanlara Ata','policy-assign')+' '+btn('İzin Türü Kuralları','policy-type')+table(['Adı','Yıllık Hak','Çalışan','İşlem'],store.state.policies.map((p,i)=>[esc(p.name),`${p.annualDays} gün`,store.state.employees.filter(e=>e.policyId===p.id||!e.policyId&&i===0).length,btn('Düzenle','policy','text-button',`data-id="${p.id}"`)]));if(sub==='approval')return panel('Onay Süreci',`<p>Çalışan → ${store.state.approvalSteps.map(esc).join(' → ')} → Onaylandı</p>${btn('Süreci Düzenle','approval')}`,'git-branch');if(sub==='calendar')return advanced.views.calendar(true);return `<div class="subtabs">${[['pending','Onay Bekleyenler'],['approved','Onaylananlar'],['rejected','Reddedilenler'],['all','Tümü']].map(([v,l])=>btn(l,'request-filter',(sessionStorage.getItem('ik2.requestFilter')||'pending')===v?'active':'',`data-status="${v}"`)).join('')}</div>${requestsTable(store.readable('requests').filter(r=>r.type==='İzin'&&((sessionStorage.getItem('ik2.requestFilter')||'pending')==='all'||r.status===(sessionStorage.getItem('ik2.requestFilter')||'pending'))))}`;}
function calendar(onlyLeaves=false){if(!onlyLeaves)header('Takvim','İzin ve etkinlikleri görüntüleyin, yeni etkinlik oluşturun.',btn('Etkinlik Oluştur','record-new','primary','data-collection="events"'));const start=new Date(calendarMonth+'-01T00:00:00Z'),gridStart=new Date(start.getTime()-((start.getUTCDay()+6)%7)*DAY);const days=Array.from({length:42},(_,i)=>iso(gridStart.getTime()+i*DAY));const events=[...(!onlyLeaves?store.state.events:[]),...store.readable('requests').filter(r=>r.type==='İzin'&&r.status==='approved').map(r=>({...r,title:emp(r.employeeId).name+' · İzin'}))];return `<div class="toolbar"><div class="actions">${btn('‹','month-prev','', 'aria-label="Önceki ay"')}${btn('Bugün','month-today')}${btn('›','month-next','','aria-label="Sonraki ay"')}<h2 class="section-title">${new Intl.DateTimeFormat('tr-TR',{month:'long',year:'numeric',timeZone:'UTC'}).format(start)}</h2></div>${btn('Liste / Ay','calendar-view')}</div>`+(calendarView==='list'?table(['Etkinlik','Başlangıç','Bitiş'],events.map(e=>[esc(e.title),dateText(e.start),dateText(e.end)])):`<div class="calendar-scroll"><div class="calendar">${['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'].map(d=>`<div class="cal-head">${d}</div>`).join('')}${days.map(d=>`<div class="cal-day ${d===store.state.today?'today':''} ${d.slice(0,7)!==calendarMonth?'outside':''}"><span>${Number(d.slice(-2))}</span>${events.filter(e=>e.start<=d&&e.end>=d).map(e=>`<button class="cal-event" data-action="event-detail" data-id="${e.id}">${esc(e.title)}</button>`).join('')}</div>`).join('')}</div></div>`);}
function reports(){header('Raporlar','Şirketinizle ilgili ihtiyaç duyduğunuz raporları oluşturun.',btn('CSV İndir','report-export'));tabs([['templates','Rapor Şablonları'],['saved','Kaydedilen Rapor Şablonları']],sub||'templates');if(sub==='saved')return records('reportTemplates');const report= sessionStorage.getItem('ik2.report');if(report){let headers=['Çalışan','Şube','Departman','Unvan','İşe Başlama'],rows=store.readable('employees').map(e=>[e.name,e.branch,e.department,e.title,dateText(e.start)]);if(report==='leave'){headers=['Çalışan','Hak','Kullanılan','Bekleyen','Kalan'];rows=store.readable('employees').map(e=>{const b=balance(store.state,e.id);return[e.name,b.entitled,b.used,b.pending,b.available];});}if(report==='salary'){headers=['Çalışan','Şube','Ücret Türü','Maaş'];rows=store.readable('employees').map(e=>[e.name,e.branch,e.salaryType,money(e.salary)]);}if(report==='turnover'){headers=['Toplam','Aktif','Pasif','Pasif Oranı'];rows=[[store.state.employees.length,store.state.employees.filter(e=>e.status==='active').length,store.state.employees.filter(e=>e.status==='inactive').length,`${(store.state.employees.filter(e=>e.status==='inactive').length/store.state.employees.length*100).toFixed(1)}%`]];}reports.last=[headers,...rows];return `${btn('Şablonlara Dön','report-back')}<br><br>${table(headers,rows.map(row=>row.map(esc)))}`;}return `<h2 class="section-title">Kendin Oluştur</h2><div class="report-cards">${[['employees','Çalışan','Yaş, eğitim, birim ve çalışan bilgileri.','users'],['salary','Finans','Maaş ve birim dağılımı.','wallet'],['leave','İdari','Çalışan izin bakiyeleri.','clipboard-list'],['turnover','Çalışan Hareketleri','Aktif ve pasif çalışan dağılımı.','chart-column']].map(([id,title,desc,i])=>`<button class="report-card" data-action="report" data-report="${id}">${icon(i)}<strong>${title}</strong><p>${desc}</p></button>`).join('')}</div><h2 class="section-title">Hazır Şablonlar</h2><div class="report-cards">${[['employees','Mevcut çalışan listesi'],['leave','Çalışan izin bakiye raporu'],['salary','Maaş bilgileri'],['turnover','Çalışan hareketleri']].map(([id,title])=>`<button class="report-card" data-action="report" data-report="${id}">${icon('file-chart-column')}<strong>${title}</strong><p>Güncel demo kayıtlarından hesaplanır.</p></button>`).join('')}</div>`;}
