function payroll(){header('Bordro','Demo hesaplama çalışma alanı',btn('Bordro Oluştur','payroll-new','primary')+btn('Harici Bordro Al','payroll-import'));tabs([['periods','Dönemler'],['settings','Ayarlar'],['reports','Raporlar']],sub||'periods');const intro=notice('Bu modül basitleştirilmiş demo hesaplaması yapar. Yasal bordro, SGK bildirimi, kıdem/ihbar veya banka ödeme talimatı üretmez.');if(sub==='settings')return intro+panel('Demo Hesaplama Parametreleri',`<p>Çalışan kesintisi: %${store.state.settings.demoPayroll.employeeRate*100}</p><p>Tek oranlı örnek vergi: %${store.state.settings.demoPayroll.taxRate*100}</p><p>İşveren payı: %${store.state.settings.demoPayroll.employerRate*100}</p>`,'calculator');return intro+store.state.payrolls.map(p=>`<section class="panel"><h2>${p.month} · ${badge(p.status)}</h2><div class="panel-body">${table(['Çalışan','Brüt','Çalışan Kesintisi','Demo Vergi','Ek Ödeme','Kesinti','Demo Net','Demo Maliyet'],p.rows.map(r=>[person(r.employeeId),money(r.gross),money(r.contribution),money(r.tax),money(r.additions||0),money(r.deductions||0),money(r.net),money(r.cost)]))}<div class="stat-row"><div><span>Toplam Net</span><strong>${money(p.rows.reduce((a,r)=>a+r.net,0))}</strong></div></div>${btn('CSV İndir','payroll-export','','data-id="'+p.id+'"')}</div></section>`).join('')+(store.state.payrolls.length?'':empty('Henüz bordro dönemi oluşturulmadı.'));}
function shifts(){header('Vardiya Yönetimi','',btn('Şablonlar','shift-templates')+btn('Vardiya Ekle','shift-new','primary'));tabs([['plans','Vardiya Planları'],['settings','Ayarlar']],sub||'plans');if(sub==='settings')return settings();const start=Date.parse(store.state.today)-((new Date(store.state.today).getUTCDay()+6)%7)*DAY;const days=Array.from({length:7},(_,i)=>iso(start+i*DAY));return `<div class="toolbar"><h2 class="section-title">${dateText(days[0])} – ${dateText(days[6])}</h2>${btn('CSV İndir','shift-export')}</div><div class="week-table">${table(['Çalışan',...days.map(dateText),'Toplam'],store.state.employees.filter(e=>e.status==='active').map(e=>[person(e.id),...days.map(d=>{const sh=store.state.shifts.find(x=>x.employeeId===e.id&&x.date===d);return sh?`${sh.start} – ${sh.end}<br><small>${sh.minutes/60} saat</small>${btn('×','record-delete','text-button',`data-collection="shifts" data-id="${sh.id}" aria-label="Vardiyayı kaldır"`)}`:btn('+','shift-new','text-button',`data-employee="${e.id}" data-date="${d}" aria-label="${esc(e.name)} ${d} vardiya ekle"`);}),`${store.state.shifts.filter(x=>x.employeeId===e.id&&days.includes(x.date)).reduce((a,x)=>a+x.minutes,0)/60} sa`]))}</div>`;}
function timesheets(){header('Puantaj','Planlanan ve gerçekleşen çalışma saatleri',btn('Saat Gir','timesheet-new','primary'));return table(['Çalışan','Planlanan Saat','Gerçekleşen Saat','Fark'],store.state.employees.filter(e=>e.status==='active').map(e=>{const planned=store.state.shifts.filter(x=>x.employeeId===e.id).reduce((a,x)=>a+x.minutes,0)/60,actual=store.state.timesheets.filter(x=>x.employeeId===e.id).reduce((a,x)=>a+x.hours,0);return [person(e.id),planned,actual,(actual-planned).toFixed(2)];}))+`<h3>Günlük Kayıtlar</h3>${table(['Çalışan','Tarih','Saat','Açıklama'],store.state.timesheets.map(x=>[person(x.employeeId),dateText(x.date),x.hours,esc(x.note||'')]))}`;}
