function render(){const path=location.hash.slice(1).split('/');route=path[0]||'home';if(route==='employee'){employeeId=path[1]||store.actor;sub=path[2]||'profile';}else sub=path[1]||'';$('#tabs').innerHTML='';$('#sidebar').innerHTML=`<a class="brand" href="#home">OTOTR <em>İK2</em></a><div class="side-scroll">${btn(icon('circle-plus')+'<span>Talep</span>','request-menu','nav-item')}${nav.filter(([id])=>store.allowedRoute(id)).map(([id,title,i])=>`<a class="nav-item ${route===id?'active':''}" href="#${id}" title="${title}">${icon(i)}<span>${title}</span></a>`).join('')}</div><div class="side-bottom"><a class="nav-item" href="#discover">${icon('grid-3x3')}<span>Keşfet</span></a><a class="nav-item" href="#settings">${icon('settings')}<span>Ayarlar</span></a><a class="nav-item" href="../index.html">${icon('arrow-left')}<span>ERP’ye Dön</span></a><a class="nav-item" href="#employee/${store.actor}/profile">${avatar(emp(store.actor),true)}<span>Hesabım</span></a></div>`;const views={home,employees,employee,leaves,reports,calendar,payroll,shifts,timesheets,performance,compensation,settings,discover:extras,...advanced.views};let html;if(!store.allowedRoute(route,employeeId)){header('Erişim sınırlı');html=notice('Bu demo rolü bu sayfayı görüntüleyemez.');}else if(views[route])html=views[route]();else if(collections[route])html=records(route);else if(['expenses','overtime'].includes(route)){header(route==='expenses'?'Harcamalar ve Avanslar':'Mesai Yönetimi','',btn('Talep Oluştur','request','primary',`data-type="${route==='expenses'?'Harcama':'Fazla Mesai'}"`));html=(route==='expenses'?btn('Harcama Belgesi Bağla','receipt-link')+'<br><br>':'')+requestsTable(store.readable('requests').filter(x=>route==='expenses'?['Avans','Harcama'].includes(x.type):x.type==='Fazla Mesai'));}else if(route==='audit'){header('İşlem Geçmişi','Bu cihazdaki demo işlemleri');html=table(['Zaman','Kullanıcı','İşlem'],store.state.audit.map(x=>[dateText(x.at),esc(emp(x.actor)?.name||x.actor),esc(x.action)]));}else if(route==='notifications'){header('Bildirimler');html=table(['Çalışan','Bildirim','Durum'],store.state.notifications.map(x=>[person(x.employeeId),esc(x.text),x.read?'Okundu':btn('Okundu İşaretle','notification','text-button',`data-id="${x.id}"`)]));}else{header('Sayfa bulunamadı');html=empty('Bu sayfa bulunamadı.','<a href="#home">Ana Sayfa</a>');}$('#main').innerHTML=html;document.body.dataset.page=route;if(store.role!=='admin'){const adminActions=new Set(['policy-type','policy-assign','review-assign','compensation-chain','cloud-open','attendance-sync','attendance-import','attendance-use','payroll-import','advance-date','employee-new','employee-edit','employee-status','bulk','import-data','record-new','record-edit','record-delete','position','salary','policy','approval','work-settings','company-settings','holiday','backup','restore','timesheet-new','shift-new','assessment-score','compensation-propose','compensation-approve','compensation-apply','workflow-task','workflow-toggle','asset-return','custom-edit']);for(const button of document.querySelectorAll('[data-action]'))if(adminActions.has(button.dataset.action))button.hidden=true;}icons();}
function employeeForm(id){const e=id?emp(id):{start:store.state.today,salary:0,leaveEntitlement:20,personal:{}};modal(id?'Çalışanı Düzenle':'Yeni bir çalışan ekleyin',`<div class="form-grid">${field('name','Ad Soyad','text',e.name)}${field('email','İş E-postası','email',e.email)}${field('start','İşe Başlama Tarihi','date',e.start)}${field('branch','Şube','text',e.branch,store.state.settings.branches)}${field('department','Departman','text',e.department,store.state.settings.departments)}${field('title','Unvan','text',e.title)}${field('managerId','Yöneticisi','text',e.managerId,[['','Yönetici yok'],...employeeOptions().filter(x=>x[0]!==id)])}${field('workType','Çalışma Şekli','text',e.workType,['Tam zamanlı','Yarı zamanlı'])}${field('salary','Demo Brüt Maaş','number',e.salary)}${field('leaveEntitlement','Yıllık İzin Hakkı','number',e.leaveEntitlement)}${field('birth','Doğum Tarihi','date',e.birth)}${field('education','Eğitim','text',e.personal.education,['','Lise','Ön lisans','Lisans','Yüksek lisans','Doktora'])}${field('phone','Telefon','text',e.phone)}${field('address','Adres','text',e.personal.address)}${field('emergencyName','Acil Durum Kişisi','text',e.personal.emergencyName)}${field('emergencyPhone','Acil Durum Telefonu','text',e.personal.emergencyPhone)}</div>`,v=>store.saveEmployee({...e,...v,salaryType:'Brüt',personal:{...e.personal,education:v.education,address:v.address,emergencyName:v.emergencyName,emergencyPhone:v.emergencyPhone}},id),'Kaydet',true);}
