function recordForm(collection,id,employee=''){const r=store.state[collection].find(x=>x.id===id)||{};modal(collections[collection]?.[1]||'Kayıt',`<div class="form-grid">${field('title','Ad / Başlık','text',r.title,'',true)}${field('employeeId','Çalışan','text',r.employeeId||employee,[['','Genel'],...employeeOptions()],true)}${field('start','Başlangıç / Veriliş','date',r.start||store.state.today)}${field('end','Bitiş / İade','date',r.end||'')}${collection==='assets'?field('serial','Seri Numarası','text',r.serial):''}${collection==='candidates'?field('email','E-posta','email',r.email):''}${field('status','Durum','text',r.status||'draft',collection==='candidates'?['draft','interview','offer','hired']:['draft','published','completed'])}${field('note','Açıklama','textarea',r.note,'',true)}</div>`,v=>store.saveRecord(collection,v,id));}
document.addEventListener('click',async event=>{const target=event.target.closest('[data-action]');if(!target)return;const a=target.dataset.action,id=target.dataset.id;try{
 if(advanced.actions[a]){const handled=await advanced.actions[a](target);if(handled!==false)return;}
 if(['assessment-score','compensation-propose','compensation-approve','compensation-apply','workflow-task','workflow-toggle','asset-return'].includes(a))return;
 if(a==='close')return $('#dialog').close();if(a==='mobile')return $('#sidebar').classList.toggle('open');if(a==='tab'){return navigate(route==='employee'?`employee/${employeeId}/${target.dataset.tab}`:`${route}/${target.dataset.tab}`);}if(a==='employee-new')return employeeForm();if(a==='employee-edit')return employeeForm(employeeId);if(a==='view'){employeeView=target.dataset.view;return render();}if(a==='employee-status'){if(emp(employeeId).status==='active')store.archiveEmployee(employeeId);else store.saveEmployee({...emp(employeeId),status:'active'},employeeId);}
 if(a==='request-menu')return modal('Yeni Talep',`<div class="report-cards">${['İzin','Avans','Harcama','Fazla Mesai','Vize Belgesi'].map(type=>btn(type,'request','',`data-type="${type}"`)).join('')}</div>`,null);
 if(a==='request'){if($('#dialog').open)$('#dialog').close();return requestForm(target.dataset.type,target.dataset.employee||store.actor);}if(a==='approve')store.decide(id,'approved');if(a==='reject')return modal('Talebi Reddet',field('reason','Ret Gerekçesi','textarea','',null,true),v=>store.decide(id,'rejected',v.reason),'Reddet');if(a==='paid')store.markPaid(id);if(a==='request-cancel')store.cancel(id);
 if(a==='request-filter'){sessionStorage.setItem('ik2.requestFilter',target.dataset.status);return render();}if(a==='record-new')return recordForm(target.dataset.collection,undefined,target.dataset.employee);if(a==='record-edit')return recordForm(target.dataset.collection,id);if(a==='record-delete')return modal('Kaydı Kaldır','<p>Bu demo kaydını kaldırmak istiyor musunuz?</p>',()=>store.removeRecord(target.dataset.collection,id),'Kaldır');
 if(a==='position')return modal('Pozisyon Ekle',`<div class="form-grid">${field('start','Başlangıç','date',store.state.today)}${field('branch','Şube','text',emp(employeeId).branch,store.state.settings.branches)}${field('department','Departman','text',emp(employeeId).department,store.state.settings.departments)}${field('title','Unvan','text',emp(employeeId).title)}</div>`,v=>{const e=emp(employeeId);store.saveEmployee({...e,branch:v.branch,department:v.department,title:v.title,positions:[...e.positions,v]},employeeId);});
 if(a==='salary')return modal('Maaş Güncelle',`<div class="form-grid">${field('amount','Brüt Maaş','number',emp(employeeId).salary)}${field('start','Geçerlilik Tarihi','date',store.state.today)}</div>`,v=>{const e=emp(employeeId);store.saveEmployee({...e,salary:v.amount,salaryHistory:[...e.salaryHistory,{...v,type:'Brüt'}]},employeeId);});
 if(a==='month-prev'||a==='month-next'){const d=new Date(calendarMonth+'-01T00:00:00Z');d.setUTCMonth(d.getUTCMonth()+(a==='month-prev'?-1:1));calendarMonth=iso(d).slice(0,7);return render();}if(a==='month-today'){calendarMonth=store.state.today.slice(0,7);return render();}if(a==='calendar-view'){calendarView=calendarView==='list'?'month':'list';return render();}if(a==='event-detail'){const e=store.state.events.find(x=>x.id===id);if(e)return recordForm('events',id);const r=store.state.requests.find(x=>x.id===id);return modal('İzin Detayı',`<p>${esc(emp(r.employeeId).name)}</p><p>${dateText(r.start)} – ${dateText(r.end)}</p><p>${r.days} gün · ${esc(r.leaveType)}</p>`,null);}
 if(a==='report'){sessionStorage.setItem('ik2.report',target.dataset.report);return render();}if(a==='report-back'){sessionStorage.removeItem('ik2.report');return render();}if(a==='report-export'){if(!reports.last)throw Error('Önce rapor seçin.');return download('ik2-rapor.csv',csv(reports.last));}
 if(a==='payroll-new')return modal('Bordro Oluştur',notice('Yalnızca basitleştirilmiş demo hesaplama yapılır.')+field('month','Dönem','month',calendarMonth),v=>store.payroll(v.month),'Hesapla');if(a==='payroll-export'){const p=store.state.payrolls.find(x=>x.id===id);return download(`ik2-demo-bordro-${p.month}.csv`,csv([['DEMO - YASAL BORDRO DEĞİLDİR'],['Çalışan','Brüt','Kesinti','Demo Vergi','Demo Net'],...p.rows.map(r=>[emp(r.employeeId).name,r.gross,r.contribution,r.tax,r.net])]));}
 if(a==='shift-new')return modal('Vardiya Ekle',`<div class="form-grid">${field('employeeId','Çalışan','text',target.dataset.employee||store.actor,employeeOptions(),true)}${field('date','Tarih','date',target.dataset.date||store.state.today)}${field('breakMinutes','Mola (dakika)','number',60)}${field('start','Başlangıç','time','09:00')}${field('end','Bitiş','time','18:00')}</div>`,v=>store.shift(v));if(a==='shift-export')return download('ik2-vardiyalar.csv',csv([['Çalışan','Tarih','Başlangıç','Bitiş','Net Dakika'],...store.state.shifts.map(x=>[emp(x.employeeId).name,x.date,x.start,x.end,x.minutes])]));
 if(a==='timesheet-new')return modal('Puantaj Gir',`<div class="form-grid">${field('employeeId','Çalışan','text',store.actor,employeeOptions(),true)}${field('date','Tarih','date',store.state.today)}${field('hours','Gerçekleşen Saat','number',8)}${field('note','Açıklama','textarea','',null,true)}</div>`,v=>store.timesheet(v));
 if(a==='policy'){const p=store.state.policies[0];return modal('İzin Kuralı',`<div class="form-grid">${field('name','Kural Adı','text',p.name,null,true)}${field('annualDays','Yıllık Hak','number',p.annualDays)}${field('carry','Devir','text',p.carry,[['unlimited','Limitsiz'],['reset','Sıfırla']])}${field('minDays','En az gün','number',p.minDays)}${field('maxDays','En çok gün','number',p.maxDays)}${check('negative','Eksi bakiyeye izin ver',p.negative)}${check('calendarDays','Takvim günü hesapla',p.calendarDays)}${check('requireNote','Açıklama zorunlu',p.requireNote)}${check('requireReplacement','Yerine bakacak kişi zorunlu',p.requireReplacement)}</div>`,v=>store.policy({...v,annualDays:Number(v.annualDays),minDays:Number(v.minDays),maxDays:Number(v.maxDays)}));}
 if(a==='approval')return modal('Onay Süreci',field('steps','Onay Adımları (virgülle ayırın)','text',store.state.approvalSteps.join(', ')),v=>{store.admin();const steps=v.steps.split(',').map(x=>x.trim()).filter(Boolean);if(!steps.length||steps.length>5)throw Error('1 ile 5 arasında adım girin.');store.transaction('Onay süreci değişti',()=>store.state.approvalSteps=steps);});
 if(a==='work-settings')return modal('Çalışma Limitleri',`<div class="form-grid">${field('maxDailyHours','Günlük En Çok Saat','number',store.state.settings.maxDailyHours)}${field('maxWeeklyHours','Haftalık En Çok Saat','number',store.state.settings.maxWeeklyHours)}${check('allowLeaveConflict','İzinle çakışmaya izin ver',store.state.settings.allowLeaveConflict)}</div>`,v=>store.settings({maxDailyHours:Number(v.maxDailyHours),maxWeeklyHours:Number(v.maxWeeklyHours),allowLeaveConflict:v.allowLeaveConflict}));
 if(a==='company-settings')return modal('Şirket Bilgileri',`<div class="form-grid">${field('company','Şirket','text',store.state.settings.company,null,true)}${field('branches','Şubeler (virgülle ayırın)','text',store.state.settings.branches.join(', '),null,true)}${field('departments','Departmanlar (virgülle ayırın)','text',store.state.settings.departments.join(', '),null,true)}</div>`,v=>store.settings({company:v.company,branches:v.branches.split(',').map(x=>x.trim()).filter(Boolean),departments:v.departments.split(',').map(x=>x.trim()).filter(Boolean)}));
 if(a==='holiday')return modal('Tatil Ekle',field('date','Tarih','date',store.state.today),v=>{if(!v.date)throw Error('Tarih zorunlu.');store.settings({holidays:[...new Set([...store.state.settings.holidays,v.date])].sort()});});
 if(a==='notification')store.transaction('Bildirim okundu',()=>store.state.notifications.find(x=>x.id===id).read=true);
 if(a==='bulk')return modal('Toplu İşlemler',`<div class="form-grid">${field('branch','Atanacak Şube','text','',store.state.settings.branches,null)}${field('department','Atanacak Departman','text','',store.state.settings.departments,null)}<div class="field full">${store.readable('employees').map(e=>check(e.id,esc(e.name),false)).join('')}</div></div>`,v=>{store.admin();const ids=store.state.employees.filter(x=>v[x.id]).map(x=>x.id);if(!ids.length)throw Error('En az bir çalışan seçin.');store.transaction('Toplu birim ataması',()=>ids.forEach(id=>Object.assign(store.employee(id),{branch:v.branch,department:v.department})));});
 if(a==='backup')return download('ototr-ik2-demo-yedek.json',JSON.stringify(store.state,null,2),'application/json');if(a==='restore')return modal('Demo Yedeği Geri Yükle',notice('Mevcut cihaz demo kayıtları yedekteki kayıtlarla değişir.')+'<input type="file" name="file" accept="application/json" required>',async v=>{store.admin();if(v.file.size>5000000)throw Error('Yedek 5 MB sınırını aşıyor.');const data=JSON.parse(await v.file.text());new HrStore(data);store.transaction('Demo yedeği geri yüklendi',()=>{data.revision=store.state.revision;store.state=data;});});
 if(a==='demo')return modal('Demo Seçenekleri',notice('Rol seçimi yalnızca demo davranışını sınar. Sunucu erişim yetkisi vermez.')+`<div class="form-grid">${field('actor','Demo Kullanıcı','text',store.actor,employeeOptions())}${field('role','Demo Rol','text',store.role,[['admin','İK Yöneticisi'],['manager','Yönetici'],['employee','Çalışan']])}</div><br>${btn('Yedeği İndir','backup')}`,v=>{store.actor=v.actor;store.role=v.role;});
 render();toast('İşlem tamamlandı.');
 }catch(error){toast(error.message);}});
document.addEventListener('input',event=>{if(event.target.id==='search'){search=event.target.value;const pos=event.target.selectionStart;render();$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos);}});
document.addEventListener('change',event=>{if(event.target.id==='employment-status'){sessionStorage.setItem('ik2.employeeStatus',event.target.value);render();}if(event.target.id==='branch'){branch=event.target.value;render();}});
$('#demo-menu').addEventListener('click',()=>{const b=document.createElement('button');b.dataset.action='demo';document.body.append(b);b.click();b.remove();});
addEventListener('hashchange',()=>{$('#sidebar').classList.remove('open');search='';render();window.scrollTo(0,0);});
addEventListener('storage',event=>{if(event.key===KEY&&event.newValue)toast('Demo verisi başka sekmede değişti. Değişiklik yapmadan önce sayfayı yenileyin.');});
function recordDetails(collection,rows){
 if(collection==='goals')return table(['Hedef','Çalışan','Hedef Değer','Gerçekleşen','İlerleme'],rows.map(g=>[esc(g.title),g.employeeId?person(g.employeeId):'Genel',esc(g.target)+' '+esc(g.unit),esc(g.actual),`${Math.round(Number(g.actual)/Number(g.target)*100)}%`]));
 if(collection==='trainings')return table(['Eğitim','Eğitmen','Süre'],rows.map(t=>[esc(t.title),esc(t.trainer),esc(t.duration)+' saat']));
 if(collection==='candidates')return rows.filter(r=>!r.hiredEmployeeId&&r.status!=='rejected').map(r=>`<div class="list-row"><span class="grow">${esc(r.title)}</span>${btn('İşe Al','candidate-hire','',`data-id="${r.id}"`)}</div>`).join('');
 if(collection==='assessments')return rows.map(a=>panel(esc(a.title),`${table(['Çalışan','Yetkinlik','Hedef','Ağırlıklı Puan'],(a.scores||[]).map(s=>[person(s.employeeId),s.competency,s.goal,s.total]))}<br>${a.status!=='completed'?(a.reviewerAssignments?.length?'<p>360° yanıtlar: '+(a.reviews?.length||0)+' / '+a.reviewerAssignments.reduce((s,r)=>s+r.reviewers.length,0)+'</p>':btn('Puan Gir','assessment-score','',`data-id="${a.id}"`))+(!a.scores?.length&&!a.reviews?.length?btn('360° Değerlendirici Ata','review-assign','',`data-id="${a.id}"`):''):badge('completed')}`,'trophy')).join('');
 if(collection==='compensations')return rows.map(c=>panel(esc(c.title),`${table(['Çalışan','Mevcut','Teklif','Değişim','Durum','İşlem'],(c.proposals||[]).map(p=>[person(p.employeeId),money(p.previous),money(p.proposed),`${p.change}%`,badge(p.status),p.status==='pending'?btn('Onayla','compensation-approve','text-button',`data-id="${c.id}" data-employee="${p.employeeId}"`):'—']))}<br>${c.status!=='completed'?btn('Teklif Ekle','compensation-propose','',`data-id="${c.id}"`)+(!c.proposals?.length?btn('Onay Sırası','compensation-chain','',`data-id="${c.id}"`):'')+' '+btn('Onaylı Ücretleri Uygula','compensation-apply','primary',`data-id="${c.id}"`):badge('completed')}`,'wallet')).join('');
 if(collection==='workflows')return rows.map(w=>panel(esc(w.title),`${(w.tasks||[]).map(t=>`<div class="list-row">${btn(t.done?'Tamamlandı':'Tamamla','workflow-toggle',t.done?'text-button':'',`data-id="${w.id}" data-task="${t.id}"`)}<span>${esc(t.title)}</span></div>`).join('')}${btn('Görev Ekle','workflow-task','',`data-id="${w.id}"`)}`,'workflow')).join('');
 if(collection==='assets')return rows.filter(a=>a.status!=='completed').map(a=>`<div class="list-row"><span class="grow">${esc(a.title)} · ${esc(emp(a.employeeId)?.name||'Atanmamış')}</span>${btn('İade Al','asset-return','text-button',`data-id="${a.id}"`)}</div>`).join('');
 return '';
}
document.addEventListener('click',event=>{const t=event.target.closest('[data-action]');if(!t)return;const a=t.dataset.action,id=t.dataset.id;if(advanced.actions[a])return;try{
 if(a==='assessment-score')return modal('Performans Puanı',`<div class="form-grid">${field('employeeId','Çalışan','text',store.actor,employeeOptions(),true)}${field('competency','Yetkinlik (0–100)','number',75)}${field('goal','Hedef (0–100)','number',80)}${field('note','Geri Bildirim','textarea','',null,true)}</div>`,v=>store.scoreAssessment(id,v.employeeId,v));
 if(a==='compensation-propose')return modal('Ücret Teklifi',field('employeeId','Çalışan','text',store.actor,employeeOptions())+'<br>'+field('amount','Önerilen Brüt Maaş','number',''),v=>store.compensationProposal(id,v.employeeId,v.amount));
 if(a==='compensation-approve'){store.approveCompensation(id,t.dataset.employee);render();toast('Demo teklif onaylandı.');}
 if(a==='compensation-apply')return modal('Onaylı Ücretleri Uygula','<p>Onaylı teklifleri demo çalışanların maaşlarına uygulayıp süreci tamamlamak istiyor musunuz?</p>',()=>store.applyCompensation(id),'Uygula');
 if(a==='workflow-task')return modal('Görev Ekle',field('title','Görev','text',''),v=>store.workflowTask(id,v.title));
 if(a==='workflow-toggle'){store.completeTask(id,t.dataset.task);render();}
 if(a==='asset-return')return modal('Zimmet İadesi',field('date','İade Tarihi','date',store.state.today),v=>store.returnAsset(id,v.date));
 }catch(error){toast(error.message);}});
const advanced=createAdvanced({store,field,check,btn,modal,table,header,tabs,panel,notice,download,person,render,navigate,toast,requestsTable,performance,compensation,context:()=>({route,sub,employeeId})});
render();

function refreshWorkDate(){try{const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());if(today>=store.state.today){const before=store.state.revision;store.advanceDate(today,{automatic:true});if(before!==store.state.revision)render();}}catch(error){toast(error.message);}}
refreshWorkDate();
setInterval(refreshWorkDate,60000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshWorkDate();});
